    [100+Math.cos(t*0.6+1)*70, 190+Math.sin(t*0.45+3)*50, 0.11, 1.6, 0.9],
    [380+Math.sin(t*0.32+4)*80, 170+Math.cos(t*0.7+2)*60, 0.065, 2.8, 1.1],
