    aS += Math.sin(d*f-t*sp)*w;
    iS1 += Math.sin(d*f*0.65+t*sp*0.5+1.2)*w;
    iS2 += Math.sin(d*f*0.45-t*sp*0.35+2.8)*w*0.6;
