  }
  aS/=wSum; iS1/=wSum; iS2/=wSum;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95))/2;
  const bg2 = Math.sin((sx+sy)*0.1+t*2.2)*0.25+Math.sin((sx-sy)*0.085-t*1.8)*0.25;
